//--------------------------------------------------------------------------//

void dei_sc_info_set( DEI_SC_INFO info , UInt8 status )
{
    bitfield_wr( dei_sc_info.bits , (info&0xFF) , (info >> 8)&0xFF , status ) ; 
}

//--------------------------------------------------------------------------//

UInt8 dei_sc_info_get( DEI_SC_INFO info )
{
    return bitfield_rd( dei_sc_info.bits , (info&0xFF) , (info >> 8)&0xFF  ) ; 
}

//--------------------------------------------------------------------------//

void dei_sc_info_clr( void  )
{
    UInt8 i ; 

    for( i = 0 ; i < (DEI_SC_INFO_BIT_COUNT / 8)  + 1 ; i  ++ )
    {
        dei_sc_info.bits[i] = 0 ; 
    }
}

